database.kode_skema:
-- Ekstensi untuk UUID
create extension if not exists "pgcrypto";

-- Tabel profil (ekstensi auth.users Supabase)
create table profil (
  id uuid primary key references auth.users(id) on delete cascade,
  nama_lengkap text,
  email text unique not null,
  peran text not null default 'pelanggan' check (peran in ('pelanggan','admin')),
  dibuat_pada timestamptz not null default now()
);

-- Tabel anak_tersimpan
create table anak_tersimpan (
  id uuid primary key default gen_random_uuid(),
  pengguna_id uuid not null references profil(id) on delete cascade,
  nama_anak text not null,
  kelas text,
  nama_sekolah text not null,
  catatan_alergi text,
  dibuat_pada timestamptz not null default now()
);

-- Tabel menu
create table menu (
  id uuid primary key default gen_random_uuid(),
  nama_menu text not null,
  deskripsi text,
  bahan text,
  alergen text,
  foto_url text,
  tanggal_sajian date not null,
  stok_harian integer not null default 0,
  status text not null default 'tersedia' check (status in ('tersedia','habis','nonaktif')),
  dibuat_oleh uuid references profil(id),
  dibuat_pada timestamptz not null default now(),
  diubah_pada timestamptz not null default now()
);

-- Tabel paket
create table paket (
  id uuid primary key default gen_random_uuid(),
  nama_paket text not null,
  durasi text not null check (durasi in ('harian','mingguan')),
  harga_per_porsi integer not null check (harga_per_porsi >= 0),
  harga_paket integer check (harga_paket >= 0),
  deskripsi text,
  status_aktif boolean not null default true,
  dibuat_pada timestamptz not null default now(),
  diubah_pada timestamptz not null default now()
);

-- Tabel kupon
create table kupon (
  id uuid primary key default gen_random_uuid(),
  kode_kupon text unique not null,
  persen_diskon integer not null check (persen_diskon between 1 and 100),
  hanya_pelanggan_baru boolean not null default true,
  berlaku_dari timestamptz not null default now(),
  berlaku_sampai timestamptz not null,
  dibuat_oleh uuid references profil(id),
  dibuat_pada timestamptz not null default now()
);

-- Tabel pesanan (mendukung tamu dan pelanggan terdaftar)
create table pesanan (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references profil(id) on delete set null,
  nama_tamu text,
  kontak_tamu text,
  nama_anak_snapshot text not null,
  kelas_snapshot text,
  nama_sekolah_snapshot text not null,
  catatan_alergi_snapshot text,
  paket_id uuid references paket(id),
  nama_paket_snapshot text not null,
  durasi_snapshot text not null check (durasi_snapshot in ('harian','mingguan')),
  harga_satuan_snapshot integer not null check (harga_satuan_snapshot >= 0),
  jumlah_porsi integer not null check (jumlah_porsi > 0),
  tanggal_pengiriman date not null,
  kupon_id uuid references kupon(id),
  kode_kupon_snapshot text,
  persen_diskon_snapshot integer,
  total_harga_snapshot integer not null check (total_harga_snapshot >= 0),
  status text not null default 'baru' check (status in ('baru','diproses','dikirim','selesai','dibatalkan')),
  dibuat_pada timestamptz not null default now(),
  diubah_pada timestamptz not null default now(),
  constraint cek_identitas_pemesan check (user_id is not null or (nama_tamu is not null and kontak_tamu is not null))
);

-- Tabel item_pesanan_menu (teknis, rincian menu per pesanan)
create table item_pesanan_menu (
  id uuid primary key default gen_random_uuid(),
  pesanan_id uuid not null references pesanan(id) on delete cascade,
  menu_id uuid references menu(id) on delete set null,
  nama_menu_snapshot text not null,
  foto_url_snapshot text,
  tanggal_sajian_snapshot date not null,
  dibuat_pada timestamptz not null default now()
);

-- Tabel log_audit (teknis, append-only)
create table log_audit (
  id uuid primary key default gen_random_uuid(),
  aktor_id uuid references profil(id),
  aksi text not null,
  entitas text not null,
  entitas_id uuid not null,
  ringkasan_perubahan text not null,
  dibuat_pada timestamptz not null default now()
);

-- Indeks pendukung
create index idx_menu_tanggal on menu(tanggal_sajian);
create index idx_pesanan_user on pesanan(user_id);
create index idx_pesanan_tanggal on pesanan(tanggal_pengiriman);
create index idx_log_audit_entitas on log_audit(entitas, entitas_id);

-- Aktifkan RLS
alter table profil enable row level security;
alter table anak_tersimpan enable row level security;
alter table menu enable row level security;
alter table paket enable row level security;
alter table kupon enable row level security;
alter table pesanan enable row level security;
alter table item_pesanan_menu enable row level security;
alter table log_audit enable row level security;

-- Fungsi bantu cek peran admin
create or replace function is_admin() returns boolean as $$
  select exists (
    select 1 from profil where id = auth.uid() and peran = 'admin'
  );
$$ language sql security definer stable;

-- Kebijakan profil
create policy profil_lihat_sendiri on profil for select using (id = auth.uid() or is_admin());
create policy profil_update_sendiri on profil for update using (id = auth.uid());

-- Kebijakan anak_tersimpan
create policy anak_lihat_sendiri on anak_tersimpan for select using (pengguna_id = auth.uid() or is_admin());
create policy anak_insert_sendiri on anak_tersimpan for insert with check (pengguna_id = auth.uid());
create policy anak_update_sendiri on anak_tersimpan for update using (pengguna_id = auth.uid());
create policy anak_delete_sendiri on anak_tersimpan for delete using (pengguna_id = auth.uid());

-- Kebijakan menu (publik baca, admin kelola)
create policy menu_baca_publik on menu for select using (true);
create policy menu_kelola_admin on menu for insert with check (is_admin());
create policy menu_update_admin on menu for update using (is_admin());
create policy menu_delete_admin on menu for delete using (is_admin());

-- Kebijakan paket (publik baca, admin kelola)
create policy paket_baca_publik on paket for select using (true);
create policy paket_kelola_admin on paket for insert with check (is_admin());
create policy paket_update_admin on paket for update using (is_admin());
create policy paket_delete_admin on paket for delete using (is_admin());

-- Kebijakan kupon (baca terbatas untuk cek kode, kelola oleh admin)
create policy kupon_baca_terbatas on kupon for select using (true);
create policy kupon_kelola_admin on kupon for insert with check (is_admin());
create policy kupon_update_admin on kupon for update using (is_admin());
create policy kupon_delete_admin on kupon for delete using (is_admin());

-- Kebijakan pesanan (pemilik data atau admin)
create policy pesanan_lihat_sendiri on pesanan for select using (user_id = auth.uid() or is_admin());
create policy pesanan_insert_publik on pesanan for insert with check (user_id = auth.uid() or user_id is null);
create policy pesanan_update_admin on pesanan for update using (is_admin());

-- Kebijakan item_pesanan_menu (ikut akses pesanan induk)
create policy item_pesanan_lihat on item_pesanan_menu for select using (
  exists (select 1 from pesanan p where p.id = pesanan_id and (p.user_id = auth.uid() or is_admin()))
);
create policy item_pesanan_insert on item_pesanan_menu for insert with check (
  exists (select 1 from pesanan p where p.id = pesanan_id and (p.user_id = auth.uid() or p.user_id is null))
);

-- Kebijakan log_audit (hanya admin baca, hanya admin insert, tidak ada update/delete)
create policy log_audit_baca_admin on log_audit for select using (is_admin());
create policy log_audit_insert_admin on log_audit for insert with check (is_admin());
